#!/usr/bin/perl
use strict; use warnings;
my $BIN="/workspace/dataset/test13_executable";
sub run { my ($w)=@_;
  my $pid=open(my $fh, "-|") or do { exec($BIN,$w); die; };
  local $/; my $out=<$fh>; close($fh); return defined($out)?$out:"";
}
