# argv: hex-encoded W strings
for my $h (@ARGV) {
  my $w = pack("H*",$h);
  my $out = run($w);
  my @L = split(/\n/, $out, -1);
  # print all lines with index
  printf("W=[%s] nlines=%d\n", esc($w), scalar(@L)-1);
