cat > /tmp/b.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings;
my $BIN="/workspace/dataset/test13_executable";
sub run { my ($w)=@_;
  open(my $fh, "-|") or do { exec($BIN,$w); die; };
  local $/; my $out=<$fh>; close($fh); return defined($out)?$out:"";
}
sub esc { my ($s)=@_; $s=~s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge; return $s; }
# probe each byte value in "A<b>B"
for my $b (1..255) {
  next if $b==0x0A; # handled separately
  my $w = "A".chr($b)."B";
  my $out = run($w);
  my @L = split(/\n/, $out, -1);
  my $n = scalar(@L)-1;
  my $l10 = ($n>=10)? $L[9] : "??NLINES=$n";
  printf("b=0x%02X %-6s L10=|%s|%s\n", $b, ($b>=0x20&&$b<0x7f)?"'".chr($b)."'":"", esc($l10), ($n!=13)?" [nlines=$n]":"");
}
EOF
perl /tmp/b.pl 2>&1
